param([string]$InDir='pages/apps/abbey/imports/transactions',[string]$OutFile='pages/apps/abbey/ledger.json') $ErrorActionPreference='Stop'; $root=Split-Path -Parent $PSScriptRoot; $inAbs=Join-Path $root $InDir; $outAbs=Join-Path $root $OutFile; if(-not (Test-Path $inAbs)){ Write-Error "No CSV imports at $inAbs"; exit 1 } $files=Get-ChildItem -Path $inAbs -Filter '*.csv' -File -Recurse; if(-not $files){ Write-Error "No CSV files in $inAbs"; exit 1 } $rows=@(); foreach($f in $files){ $data=Import-Csv -Path $f.FullName; foreach($r in $data){ $date=$r.date ?? $r.Date ?? $r.PostedDate ?? $r.TransactionDate; $desc=$r.description ?? $r.Description ?? $r.Memo ?? $r.Details; $amt=$r.amount ?? $r.Amount ?? $r.Debit ?? $r.Credit; if([string]::IsNullOrWhiteSpace($desc)){ continue } $v=[double]0; try{ $v=[double]$amt } catch { continue } $rows += @{ date=$date; vendor=$desc; amount=$v } } } $ledger=@{ updated=(Get-Date).ToUniversalTime().ToString('s')+'Z'; rows=$rows }; $dirOut=Split-Path -Parent $outAbs; if(-not (Test-Path $dirOut)){ New-Item -ItemType Directory -Force -Path $dirOut | Out-Null }; [IO.File]::WriteAllText($outAbs,($ledger|ConvertTo-Json -Depth 6),[Text.Encoding]::UTF8); Write-Host "Ledger -> $OutFile with $($rows.Count) rows"